/* ALDOL SOUND MCP v0.4.1 direct-delivery bridge.
 * Accepts ONLY original server-generated bytes. Does not synthesize or fetch sounds.
 * Runtime: Cloudflare Workers / modern JS with WebCrypto and btoa.
 * Additive integration: retain original URL and existing data, add opt-in MCP inline output.
 */
export const INLINE_LIMIT_BYTES = 131072; // 128 KiB; finite output and memory budget

export class InlineDeliveryError extends Error {
  constructor(code, message) { super(message); this.name = 'InlineDeliveryError'; this.code = code; }
}

function asBytes(value) {
  if (value instanceof Uint8Array) return value;
  if (value instanceof ArrayBuffer) return new Uint8Array(value);
  if (ArrayBuffer.isView(value)) return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  throw new InlineDeliveryError('INVALID_BYTES', 'Original generated file bytes must be provided as Uint8Array or ArrayBuffer');
}

function base64Encode(bytes) {
  let encoded = '';
  // multiple of 3, so no base64 padding is introduced between chunks
  const chunk = 24576;
  for (let i = 0; i < bytes.length; i += chunk) {
    const sub = bytes.subarray(i, i + chunk);
    let chars = '';
    for (let j = 0; j < sub.length; j++) chars += String.fromCharCode(sub[j]);
    encoded += btoa(chars);
  }
  return encoded;
}

async function sha256Hex(bytes) {
  const sha = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  return [...sha].map(x => x.toString(16).padStart(2, '0')).join('');
}

function requireMetadata(meta, type) {
  if (!meta || typeof meta !== 'object') throw new InlineDeliveryError('INVALID_METADATA', 'Missing existing MCP result metadata');
  if (!Number.isSafeInteger(meta.byte_length) || meta.byte_length < 1) throw new InlineDeliveryError('INVALID_METADATA', 'Missing byte_length');
  if (!/^[0-9a-f]{64}$/.test(meta.sha256 || '')) throw new InlineDeliveryError('INVALID_METADATA', 'Missing SHA-256');
  const expectedMime = type === 'wav' ? 'audio/wav' : 'application/zip';
  if (meta.mime_type !== expectedMime) throw new InlineDeliveryError('INVALID_MIME', `Expected ${expectedMime}`);
}

function checkFormat(bytes, type) {
  if (type === 'wav') {
    if (bytes.length < 44) throw new InlineDeliveryError('INVALID_WAV', 'WAV is too short');
    const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const word = off => String.fromCharCode(...bytes.subarray(off, off + 4));
    if (word(0) !== 'RIFF' || word(8) !== 'WAVE') throw new InlineDeliveryError('INVALID_WAV', 'WAV RIFF/WAVE header invalid');
    if (dv.getUint32(4, true) + 8 !== bytes.length) throw new InlineDeliveryError('INVALID_WAV', 'WAV RIFF size mismatch');
    let offset = 12, fmt = null, dataBytes = null;
    while (offset + 8 <= bytes.length) {
      const kind = word(offset);
      const length = dv.getUint32(offset + 4, true);
      if (offset + 8 + length > bytes.length) throw new InlineDeliveryError('INVALID_WAV', 'WAV chunk extends beyond file');
      if (kind === 'fmt ') {
        if (length < 16) throw new InlineDeliveryError('INVALID_WAV', 'Short WAV fmt chunk');
        fmt = {
          encoding:dv.getUint16(offset + 8,true), channels:dv.getUint16(offset + 10,true),
          sampleRate:dv.getUint32(offset + 12,true), byteRate:dv.getUint32(offset + 16,true),
          blockAlign:dv.getUint16(offset + 20,true), bitDepth:dv.getUint16(offset + 22,true)
        };
      }
      if (kind === 'data') dataBytes = length;
      offset += 8 + length + (length % 2);
    }
    if (!fmt || dataBytes === null || fmt.encoding !== 1 || fmt.channels !== 1 || fmt.bitDepth !== 16 ||
        ![22050,44100,48000].includes(fmt.sampleRate) || fmt.blockAlign !== 2 || fmt.byteRate !== 2 * fmt.sampleRate ||
        dataBytes % fmt.blockAlign !== 0) throw new InlineDeliveryError('INVALID_WAV','Expected mono PCM16 WAV with supported sample rate');
  } else if (type === 'zip') {
    const header = bytes.length >= 4 ? String.fromCharCode(...bytes.subarray(0, 4)) : '';
    if (!['PK\x03\x04', 'PK\x05\x06'].includes(header)) throw new InlineDeliveryError('INVALID_ZIP', 'ZIP signature invalid');
  } else throw new InlineDeliveryError('INVALID_TYPE', 'Allowed: wav or zip');
}

/**
 * @param {Object} options
 * @param {'wav'|'zip'} options.type
 * @param {Object} options.existingResult - original sound_generate or sound_export_pack structured response
 * @param {Uint8Array|ArrayBuffer} options.generatedBytes - EXACT ORIGINAL bytes from generator, never re-rendered or fetched URL
 * @param {number} [options.maxInlineBytes] - hard cap for transport. Do not override upward without deliberate review.
 * @returns {Promise<{content:Array,structuredContent:Object,isError?:boolean}>}
 */
export async function wrapGeneratedFileInline({type, existingResult, generatedBytes, maxInlineBytes = INLINE_LIMIT_BYTES}) {
  requireMetadata(existingResult, type);
  const bytes = asBytes(generatedBytes);
  if (!Number.isSafeInteger(maxInlineBytes) || maxInlineBytes < 1 || maxInlineBytes > INLINE_LIMIT_BYTES) {
    throw new InlineDeliveryError('INVALID_LIMIT', 'Inline byte ceiling must be within the configured 128 KiB limit');
  }
  if (bytes.length > maxInlineBytes) throw new InlineDeliveryError('INLINE_TOO_LARGE', `File is ${bytes.length} bytes; max ${maxInlineBytes}. Original URL delivery remains available.`);
  if (existingResult.byte_length !== bytes.length) throw new InlineDeliveryError('BYTE_LENGTH_MISMATCH', 'Original metadata byte_length does not match generated bytes');
  checkFormat(bytes, type);
  const actualSha = await sha256Hex(bytes);
  if (actualSha !== existingResult.sha256) throw new InlineDeliveryError('SHA256_MISMATCH', 'Original metadata SHA-256 does not match generated bytes');
  const encoded = base64Encode(bytes);
  const inline = {encoding:'base64', mime_type: existingResult.mime_type, byte_length: bytes.length, sha256:actualSha, data:encoded};
  const structuredContent = {...existingResult, inline_delivery: inline};
  const media = type === 'wav'
    ? {type:'audio', data:encoded, mimeType:'audio/wav'}
    : {type:'resource', resource:{uri:`aldol://sound-pack/${actualSha}.zip`, mimeType:'application/zip', blob:encoded}};
  return {content:[{type:'text',text:JSON.stringify({filename:existingResult.filename,sha256:actualSha,byte_length:bytes.length,inline:true})}, media],structuredContent};
}

export function toMcpInlineError(err) {
  const code = err instanceof InlineDeliveryError ? err.code : 'INLINE_DELIVERY_ERROR';
  const message = err instanceof InlineDeliveryError ? err.message : 'Inline file transport failed';
  return {isError:true,content:[{type:'text',text:`${code}: ${message}`}],structuredContent:{error:{code,message}}};
}
